// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz parameters: an address that will be the `from`, a uint value, and a dynamic array length
    // We cannot fuzz an arbitrary address to act as a reverting callee; we must deploy a helper that reverts.
    function testFuzz_property(address from, uint256 v, uint8 tosLen) public {
        // keep tosLen reasonable but allow 1..10
        uint8 len = tosLen;
        if (len == 0) { len = 1; }
        if (len > 10) { len = 10; }

        // build _tos array of addresses; we will set each to the reverter helper's address
        address[] memory tos = new address[](len);

        // deploy a Reverter helper that will ALWAYS revert when called
        Reverter reverter = new Reverter();
        for (uint i = 0; i < uint(len); i++) {
            tos[i] = address(reverter);
        }

        // The rule: the reference contract C performs low-level calls to caddress and will revert
        // if any of those calls revert. Here we drive it with a callee that always reverts.
        // We observe whether c.transfer(...) itself reverts by catching it.

        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: For the reference implementation, calling transfer with a callee that reverts
        // causes transfer to revert (ok == false) for ALL admissible inputs. The mutant that removed
        // the external call will make transfer succeed (ok == true) for those same inputs. Therefore
        // we assert that this call DID revert (ok == false). This will pass on the correct contract
        // for all inputs and fail on the mutant for some inputs (indeed for all inputs here).
        assertTrue(ok == false);
    }
}

contract Reverter {
    // This function matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    // but we can simply revert in fallback so that low-level call from C fails.
    fallback() external payable {
        revert("revert-from-helper");
    }

    // also include the concrete function signature so well-formed ABI calls hit a revert path too
    function transferFrom(address, address, uint256) external pure {
        revert("revert-from-helper");
    }
}
